import { useMemo, useState } from 'react';
import type { ElementType, FormEvent, ReactNode } from 'react';
import { Link, useLocation } from 'wouter';
import { useQueryClient } from '@tanstack/react-query';
import {
  AlertTriangle, ArrowUpRight, BarChart3, Bell, CalendarDays, Camera, Check,
  ChevronRight, CircleHelp, CloudRain, CloudSun, Droplets, FileText, FlaskConical,
  Info, Leaf, LocateFixed, Menu, MessageCircle, Microscope, Plus, RefreshCw,
  ScanLine, Search, Send, Sprout, Upload, Wind, X,
} from 'lucide-react';
import {
  getGetDashboardQueryKey, getListAlertsQueryKey, getListCropsQueryKey,
  getListReportsQueryKey, getListSoilReportsQueryKey, useCreateCrop,
  useCreateSoilReport, useGetDashboard, useListAlerts, useListCrops,
  useListReports, useListSoilReports,
} from '@workspace/api-client-react';
import type { Alert, Crop, Dashboard, Report, SoilReport, Weather } from '@workspace/api-client-react';

const navItems = [
  { href: '/', label: 'Overview', icon: LayoutDashboardIcon },
  { href: '/scan', label: 'Crop scan', icon: ScanLine },
  { href: '/nutrients', label: 'Nutrient eye', icon: Microscope },
  { href: '/soil', label: 'Soil reports', icon: FlaskConical },
  { href: '/weather', label: 'Weather desk', icon: CloudSun },
  { href: '/assistant', label: 'Ask Patil', icon: MessageCircle },
  { href: '/crops', label: 'My crops', icon: Sprout },
  { href: '/reports', label: 'Saved reports', icon: FileText },
  { href: '/alerts', label: 'Alerts', icon: Bell },
];

function LayoutDashboardIcon(props: { size?: number }) {
  return <BarChart3 {...props} />;
}

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(' ');
}

function BrandMark({ compact = false }: { compact?: boolean }) {
  return (
    <div className={cn('flex items-center gap-3', compact && 'gap-2')} data-testid="brand-patil-agro">
      <div className="relative flex h-10 w-10 items-center justify-center rounded-[13px] bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))] shadow-sm">
        <Leaf size={21} strokeWidth={2.5} />
        <span className="absolute -bottom-1 right-0 h-3 w-3 rounded-full border-2 border-[hsl(var(--sidebar))] bg-[hsl(var(--accent))]" />
      </div>
      {!compact && <div><div className="font-serif text-[19px] font-semibold leading-none tracking-tight">Patil Agro</div><div className="mt-1 font-mono text-[9px] uppercase tracking-[.18em] text-[hsl(var(--sidebar-foreground)/.58)]">Field intelligence</div></div>}
    </div>
  );
}

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  return (
    <div className="grain min-h-[100dvh] bg-[hsl(var(--background))]">
      <aside className={cn('fixed inset-y-0 left-0 z-40 flex w-[252px] flex-col border-r border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar))] px-5 py-6 text-[hsl(var(--sidebar-foreground))] transition-transform duration-300 md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}>
        <div className="flex items-start justify-between"><BrandMark /><button className="rounded-lg p-1 md:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation" data-testid="button-close-navigation"><X size={20} /></button></div>
        <div className="mt-10 px-2 font-mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--sidebar-foreground)/.48)]">Your field desk</div>
        <nav className="mt-3 flex flex-1 flex-col gap-1" aria-label="Main navigation">
          {navItems.map(({ href, label, icon: Icon }) => (
            <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={cn('group flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-medium transition-colors', location === href ? 'bg-[hsl(var(--sidebar-accent))] text-[hsl(var(--sidebar-accent-foreground))]' : 'text-[hsl(var(--sidebar-foreground)/.72)] hover:bg-[hsl(var(--sidebar-accent)/.7)] hover:text-[hsl(var(--sidebar-foreground))]')} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}>
              <Icon size={17} strokeWidth={location === href ? 2.4 : 1.8} /><span>{label}</span>{href === '/alerts' && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-[hsl(var(--sidebar-primary))]" />}
            </Link>
          ))}
        </nav>
        <div className="rounded-2xl border border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-accent)/.5)] p-4">
          <div className="flex items-center gap-2 text-[hsl(var(--sidebar-primary))]"><CircleHelp size={16} /><span className="text-xs font-semibold">Need a second opinion?</span></div>
          <p className="mt-2 text-[11px] leading-relaxed text-[hsl(var(--sidebar-foreground)/.6)]">Share a crop photo with the field desk for a clearer next step.</p>
          <Link href="/assistant" className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-[hsl(var(--sidebar-primary))]" data-testid="link-sidebar-assistant">Open field desk <ArrowUpRight size={13} /></Link>
        </div>
        <Link href="/login" className="mt-5 flex items-center gap-3 border-t border-[hsl(var(--sidebar-border))] pt-5" data-testid="link-sidebar-profile">
          <span className="flex h-8 w-8 items-center justify-center rounded-full bg-[hsl(var(--sidebar-primary)/.18)] font-serif text-sm text-[hsl(var(--sidebar-primary))]">SP</span><span className="text-xs font-medium">Suresh Patil</span><ChevronRight className="ml-auto" size={15} />
        </Link>
      </aside>
      {mobileOpen && <button className="fixed inset-0 z-30 bg-[hsl(var(--foreground)/.3)] md:hidden" onClick={() => setMobileOpen(false)} aria-label="Close menu overlay" data-testid="button-menu-overlay" />}
      <main className="min-h-[100dvh] md:pl-[252px]">
        <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[hsl(var(--border)/.8)] bg-[hsl(var(--background)/.88)] px-5 backdrop-blur-md md:px-10">
          <button className="rounded-xl p-2 text-[hsl(var(--muted-foreground))] md:hidden" onClick={() => setMobileOpen(true)} aria-label="Open navigation" data-testid="button-open-navigation"><Menu size={21} /></button>
          <div className="hidden items-center gap-2 text-xs text-[hsl(var(--muted-foreground))] md:flex"><span className="h-2 w-2 rounded-full bg-[hsl(var(--accent))]" /> Kharadi, Pune <span className="px-1 text-[hsl(var(--border))]">/</span> Kharif season</div>
          <div className="ml-auto flex items-center gap-3"><Link href="/alerts" className="relative rounded-xl p-2 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]" data-testid="link-header-alerts"><Bell size={18} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /></Link><Link href="/assistant" className="hidden rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-semibold text-[hsl(var(--primary))] hover:bg-[hsl(var(--muted))] sm:block" data-testid="link-header-ask">Ask Patil AI</Link></div>
        </header>
        <div className="mx-auto max-w-[1440px] px-5 py-7 md:px-10 md:py-9">{children}</div>
      </main>
    </div>
  );
}

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="mb-2 font-mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">{eyebrow}</div><h1 className="font-serif text-4xl font-semibold tracking-[-.035em] text-[hsl(var(--foreground))] md:text-5xl">{title}</h1><p className="mt-2 max-w-xl text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">{description}</p></div>{action}</div>;
}

function Card({ children, className = '', ...props }: { children: ReactNode; className?: string; [key: string]: unknown }) {
  return <section className={cn('rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] shadow-[var(--shadow-sm)]', className)} {...props}>{children}</section>;
}

function LoadingBlock({ className = '' }: { className?: string }) { return <div className={cn('skeleton rounded-xl', className)} aria-label="Loading" data-testid="loading-skeleton" />; }
function ErrorState({ onRetry, label = 'We could not reach the field desk right now.' }: { onRetry?: () => void; label?: string }) {
  return <div className="rounded-2xl border border-[hsl(var(--destructive)/.2)] bg-[hsl(var(--destructive)/.05)] p-6" data-testid="state-error"><div className="flex items-start gap-3"><AlertTriangle size={19} className="mt-0.5 text-[hsl(var(--destructive))]" /><div><p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Your saved information is safe. Try again in a moment.</p>{onRetry && <button className="mt-4 inline-flex items-center gap-2 rounded-lg bg-[hsl(var(--destructive))] px-3 py-2 text-xs font-semibold text-white" onClick={onRetry} data-testid="button-retry"><RefreshCw size={13} /> Try again</button>}</div></div></div>;
}
function EmptyState({ icon: Icon, title, text, action }: { icon: ElementType; title: string; text: string; action?: ReactNode }) {
  return <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-[hsl(var(--border))] px-6 py-14 text-center" data-testid="state-empty"><div className="mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Icon size={22} /></div><p className="font-serif text-lg font-semibold">{title}</p><p className="mt-1 max-w-sm text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{text}</p>{action}</div>;
}
function SectionHeading({ title, link, href }: { title: string; link?: string; href?: string }) {
  return <div className="mb-4 flex items-center justify-between"><h2 className="font-serif text-xl font-semibold">{title}</h2>{link && href && <Link href={href} className="flex items-center gap-1 text-xs font-semibold text-[hsl(var(--primary))]" data-testid={`link-section-${href.slice(1)}`}>{link}<ChevronRight size={14} /></Link>}</div>;
}
function SeverityPill({ severity }: { severity?: string }) {
  const text = severity || 'Note'; const low = text.toLowerCase();
  return <span className={cn('rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[.08em]', low.includes('high') || low.includes('critical') ? 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))]' : low.includes('medium') || low.includes('watch') ? 'bg-[hsl(var(--accent)/.15)] text-[hsl(32,70%,34%)]' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]')}>{text}</span>;
}

function WeatherCard({ weather, large = false }: { weather?: Weather; large?: boolean }) {
  if (!weather) return <Card className="p-6"><EmptyState icon={CloudSun} title="Weather is taking a pause" text="Conditions will appear here when the local weather service is available." /></Card>;
  return <Card className={cn('relative overflow-hidden bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]', large ? 'p-7' : 'p-5')}><div className="field-lines absolute inset-0 opacity-80" /><div className="relative"><div className="flex items-start justify-between"><div><div className="flex items-center gap-1.5 text-[11px] text-[hsl(var(--primary-foreground)/.65)]"><LocateFixed size={13} />Local conditions</div><div className={cn('mt-4 font-serif font-semibold', large ? 'text-6xl' : 'text-5xl')}>{weather.temperature}<sup className="ml-1 align-top text-xl">°</sup></div><p className="mt-1 text-sm font-medium">{weather.condition}</p></div><CloudSun size={large ? 42 : 34} strokeWidth={1.2} className="text-[hsl(var(--sidebar-primary))]" /></div><div className="mt-8 grid grid-cols-3 gap-2 border-t border-[hsl(var(--primary-foreground)/.16)] pt-4"><div><p className="text-[10px] text-[hsl(var(--primary-foreground)/.58)]">Humidity</p><p className="mt-1 text-sm font-semibold">{weather.humidity}%</p></div><div><p className="text-[10px] text-[hsl(var(--primary-foreground)/.58)]">Rain chance</p><p className="mt-1 text-sm font-semibold">{weather.rainProbability}%</p></div><div><p className="text-[10px] text-[hsl(var(--primary-foreground)/.58)]">Wind</p><p className="mt-1 text-sm font-semibold">{weather.windSpeed} km/h</p></div></div></div></Card>;
}

function DashboardPage() {
  const query = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const dashboard = query.data as Dashboard | undefined;
  return <Shell><div className="page-enter">
    {query.isLoading ? <><LoadingBlock className="h-7 w-40" /><LoadingBlock className="mt-4 h-14 w-3/4" /><div className="mt-8 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><LoadingBlock className="h-52" /><LoadingBlock className="h-52" /></div></> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <>
      <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="mb-2 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /> Kharif field note</div><h1 className="font-serif text-4xl font-semibold tracking-[-.04em] md:text-5xl">Good morning, {dashboard?.farmerName || 'farmer'}.</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{dashboard?.location || 'Your farm desk'} <span className="mx-1">·</span> Here is what needs your eye today.</p></div><Link href="/scan" className="inline-flex w-fit items-center gap-2 rounded-xl bg-[hsl(var(--accent))] px-4 py-3 text-sm font-bold text-[hsl(var(--accent-foreground))] shadow-sm transition-transform hover:-translate-y-0.5" data-testid="link-start-scan"><Camera size={17} /> Check a crop</Link></div>
      <div className="grid gap-5 lg:grid-cols-[1.27fr_.73fr]"><Card className="field-lines relative overflow-hidden bg-[hsl(var(--secondary)/.7)] p-6 md:p-8"><div className="relative max-w-xl"><div className="flex items-center gap-2 text-[hsl(var(--primary))]"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[hsl(var(--primary))] text-[hsl(var(--secondary))]"><Sprout size={17} /></span><span className="text-xs font-bold uppercase tracking-[.13em]">Field pulse</span></div><h2 className="mt-7 max-w-md font-serif text-3xl font-semibold leading-[1.05] tracking-[-.03em] md:text-4xl">Small observations make <em className="text-[hsl(var(--primary))]">stronger harvests.</em></h2><p className="mt-4 max-w-md text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Use a photo, a soil report, or a simple question. We will keep the next step clear and honest.</p><div className="mt-7 flex flex-wrap gap-2"><Link href="/scan" className="rounded-lg bg-[hsl(var(--primary))] px-3.5 py-2.5 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-pulse-scan">Scan crop leaf <ArrowUpRight className="ml-1 inline" size={14} /></Link><Link href="/assistant" className="rounded-lg border border-[hsl(var(--primary)/.18)] bg-[hsl(var(--card)/.5)] px-3.5 py-2.5 text-xs font-semibold text-[hsl(var(--primary))]" data-testid="link-pulse-question">Ask a question</Link></div></div><div className="absolute -bottom-8 -right-4 hidden h-44 w-44 rounded-full border-[18px] border-[hsl(var(--accent)/.35)] md:block" /></Card><WeatherCard weather={dashboard?.weather} /></div>
      <div className="mt-9 grid gap-8 xl:grid-cols-[1.15fr_.85fr]"><div><SectionHeading title="Your active crops" link="View all crops" href="/crops" />{dashboard?.activeCrops?.length ? <div className="grid gap-3 sm:grid-cols-2">{dashboard.activeCrops.slice(0, 4).map((crop) => <CropTile key={crop.id} crop={crop} />)}</div> : <EmptyState icon={Sprout} title="Start with your first crop" text="Add a crop to see its growth stage and keep its health notes in one place." action={<Link href="/crops" className="mt-5 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-empty-add-crop">Add crop</Link>} />}</div><div><SectionHeading title="Needs your attention" link="All alerts" href="/alerts" />{dashboard?.alerts?.length ? <div className="space-y-3">{dashboard.alerts.slice(0, 3).map((alert) => <AlertRow alert={alert} key={alert.id} />)}</div> : <EmptyState icon={Bell} title="No open alerts" text="The field desk has nothing urgent for your crops right now." />}</div></div>
      <div className="mt-9"><SectionHeading title="Recent field reports" link="Open reports" href="/reports" />{dashboard?.recentReports?.length ? <div className="grid gap-3 md:grid-cols-3">{dashboard.recentReports.slice(0, 3).map((report) => <ReportTile report={report} key={report.id} />)}</div> : <EmptyState icon={FileText} title="Your report shelf is empty" text="Save the result of a crop scan to find it here later." action={<Link href="/scan" className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-empty-scan">Start a scan <ArrowUpRight size={14} /></Link>} />}</div>
    </>}</div></Shell>;
}

function CropTile({ crop }: { crop: Crop }) {
  const health = (crop.health || '').toLowerCase();
  return <Link href="/crops" className="group rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-4 transition-transform hover:-translate-y-0.5" data-testid={`card-crop-${crop.id}`}><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Sprout size={19} /></div><ArrowUpRight size={16} className="text-[hsl(var(--muted-foreground))] transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" /></div><p className="mt-5 font-serif text-lg font-semibold">{crop.name}</p><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{crop.variety} <span className="mx-1">·</span>{crop.area}</p><div className="mt-4 flex items-center justify-between border-t border-[hsl(var(--border)/.7)] pt-3"><span className="text-[11px] text-[hsl(var(--muted-foreground))]">{crop.stage}</span><span className={cn('text-[11px] font-bold', health.includes('good') || health.includes('healthy') ? 'text-[hsl(var(--primary))]' : health.includes('attention') ? 'text-[hsl(var(--destructive))]' : 'text-[hsl(var(--accent-foreground))]')}>{crop.health || 'Health pending'}</span></div></Link>;
}
function AlertRow({ alert }: { alert: Alert }) { return <Link href="/alerts" className="flex gap-3 rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-4 transition-colors hover:bg-[hsl(var(--muted)/.5)]" data-testid={`row-alert-${alert.id}`}><div className={cn('mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg', alert.severity?.toLowerCase().includes('high') ? 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))]' : 'bg-[hsl(var(--accent)/.14)] text-[hsl(var(--accent-foreground))]')}><AlertTriangle size={16} /></div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-semibold">{alert.title}</p><SeverityPill severity={alert.severity} /></div><p className="mt-1 line-clamp-2 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{alert.description}</p><p className="mt-2 font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{alert.time}</p></div></Link>; }
function ReportTile({ report }: { report: Report }) { return <Link href="/reports" className="flex gap-3 rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-4 hover:bg-[hsl(var(--muted)/.4)]" data-testid={`card-report-${report.id}`}><div className="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]">{report.imageUrl ? <img src={report.imageUrl} alt="" className="h-full w-full object-cover" /> : <FileText size={18} />}</div><div className="min-w-0"><p className="truncate text-sm font-semibold">{report.crop}</p><p className="mt-1 truncate text-xs text-[hsl(var(--muted-foreground))]">{report.disease || report.nutrient || 'Field observation'}</p><p className="mt-2 font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{report.date}</p></div></Link>; }

function ScanPage({ nutrient = false }: { nutrient?: boolean }) {
  const [phase, setPhase] = useState<'ready' | 'preview' | 'result'>('ready');
  const [fileName, setFileName] = useState('');
  const title = nutrient ? 'Nutrient eye' : 'Crop health scan';
  return <Shell><div className="page-enter"><PageIntro eyebrow={nutrient ? 'Plant nutrition' : 'Image intelligence'} title={title} description={nutrient ? 'A visual first look at possible nutrient stress. Confirm with a soil or leaf test before applying anything.' : 'Take a clear photo of the crop part that worries you. Patil AI will show possibilities, not promises.'} action={<Link href="/assistant" className="inline-flex items-center gap-2 text-xs font-semibold text-[hsl(var(--primary))]" data-testid="link-scan-help"><CircleHelp size={16} /> How to take a useful photo</Link>} /><div className="grid gap-6 lg:grid-cols-[1fr_.78fr]"><Card className="p-5 md:p-7"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] pb-5"><div><p className="font-serif text-xl font-semibold">{phase === 'result' ? 'A careful first read' : 'Bring a leaf into focus'}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Step {phase === 'ready' ? '1' : phase === 'preview' ? '2' : '3'} of 3</p></div><div className="flex gap-1.5">{[1, 2, 3].map((step) => <span key={step} className={cn('h-1.5 w-8 rounded-full', step <= (phase === 'ready' ? 1 : phase === 'preview' ? 2 : 3) ? 'bg-[hsl(var(--accent))]' : 'bg-[hsl(var(--muted))]')} />)}</div></div>{phase === 'ready' && <div className="mt-6"><div className="flex min-h-[280px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-[hsl(var(--border))] bg-[hsl(var(--background))] px-6 text-center"><div className="mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Camera size={29} strokeWidth={1.5} /></div><p className="font-serif text-xl font-semibold">Upload a crop photo</p><p className="mt-2 max-w-xs text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">A single leaf or a small patch works best. Avoid blurry, dark, or distant photos.</p><div className="mt-6 flex flex-wrap justify-center gap-2"><button onClick={() => setPhase('preview')} className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-open-camera"><Camera size={15} /> Take photo</button><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary))]" data-testid="button-upload-photo"><Upload size={15} /> Choose file<input type="file" accept="image/*" className="hidden" onChange={(event) => { setFileName(event.target.files?.[0]?.name || 'photo selected'); setPhase('preview'); }} data-testid="input-crop-photo" /></label></div></div><div className="mt-5 grid gap-2 text-xs text-[hsl(var(--muted-foreground))] sm:grid-cols-3"><div className="rounded-xl bg-[hsl(var(--muted)/.65)] p-3"><Check size={14} className="mb-2 text-[hsl(var(--primary))]" />Good daylight</div><div className="rounded-xl bg-[hsl(var(--muted)/.65)] p-3"><Check size={14} className="mb-2 text-[hsl(var(--primary))]" />Leaf fills frame</div><div className="rounded-xl bg-[hsl(var(--muted)/.65)] p-3"><Check size={14} className="mb-2 text-[hsl(var(--primary))]" />One crop at a time</div></div></div>}{phase === 'preview' && <div className="mt-6"><div className="flex min-h-[280px] flex-col items-center justify-center rounded-2xl bg-[hsl(var(--primary)/.08)] text-center"><div className="flex h-16 w-16 items-center justify-center rounded-full border-4 border-[hsl(var(--accent))] bg-[hsl(var(--card))] text-[hsl(var(--primary))]"><Check size={28} /></div><p className="mt-5 font-serif text-xl font-semibold">{fileName || 'Photo ready for review'}</p><p className="mt-2 max-w-sm text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">The photo is only used for this check. Review the quality before asking Patil AI to read it.</p></div><div className="mt-5 flex justify-between"><button onClick={() => setPhase('ready')} className="rounded-xl border border-[hsl(var(--border))] px-4 py-3 text-xs font-semibold" data-testid="button-retake-photo">Choose another</button><button onClick={() => setPhase('result')} className="rounded-xl bg-[hsl(var(--primary))] px-5 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-analyze-photo">Read this photo <ArrowUpRight className="ml-1 inline" size={14} /></button></div></div>}{phase === 'result' && <div className="mt-6"><div className="rounded-2xl border border-[hsl(var(--accent)/.35)] bg-[hsl(var(--accent)/.08)] p-5"><div className="flex items-center justify-between"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.1em] text-[hsl(var(--accent-foreground))]"><Info size={15} /> AI observation</div><span className="font-mono text-[10px] text-[hsl(var(--muted-foreground))]">not a diagnosis</span></div><p className="mt-5 font-serif text-2xl font-semibold">{nutrient ? 'Possible nitrogen stress' : 'Possible leaf spot pattern'}</p><p className="mt-2 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">This image has some matching visual signals, but image quality and field conditions can change the reading.</p><div className="mt-5 h-2 overflow-hidden rounded-full bg-[hsl(var(--card))]"><div className="h-full w-[68%] rounded-full bg-[hsl(var(--accent))]" /></div><div className="mt-2 flex justify-between text-[10px] text-[hsl(var(--muted-foreground))]"><span>Confidence range</span><span>Moderate · 68%</span></div></div><div className="mt-4 rounded-2xl border border-[hsl(var(--border))] p-5"><p className="text-xs font-bold uppercase tracking-[.1em] text-[hsl(var(--primary))]">Next sensible step</p><p className="mt-3 text-sm leading-relaxed">Compare three to five plants across the same patch. Note recent irrigation and weather, then use the assistant or a local agronomist before treatment.</p></div><div className="mt-5 flex gap-2"><button onClick={() => setPhase('ready')} className="rounded-xl border border-[hsl(var(--border))] px-4 py-3 text-xs font-semibold" data-testid="button-scan-again">Scan another</button><Link href="/assistant" className="rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-result-assistant">Discuss this result</Link></div></div>}</Card><Card className="h-fit p-6"><div className="flex items-center gap-2 text-[hsl(var(--primary))]"><Info size={17} /><p className="text-sm font-bold">A useful photo is half the answer</p></div><div className="mt-6 space-y-5">{['Wipe dust or water from the lens', 'Photograph the leaf in natural, even light', 'Include the full leaf and its edges', 'Capture one close-up and one plant view'].map((tip, index) => <div className="flex gap-3" key={tip}><span className="font-mono text-xs text-[hsl(var(--accent))]">0{index + 1}</span><p className="text-sm leading-relaxed">{tip}</p></div>)}</div><div className="mt-7 border-t border-[hsl(var(--border))] pt-5 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Visual results are a starting point. They cannot replace a lab test or advice from a qualified local agronomist.</div></Card></div></div></Shell>;
}

function CropsPage() {
  const query = useListCrops({ query: { queryKey: getListCropsQueryKey() } });
  const create = useCreateCrop();
  const client = useQueryClient();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: '', variety: '', area: '', stage: 'Vegetative', sowingDate: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name || !form.variety || !form.area || !form.sowingDate) return; create.mutate({ data: form }, { onSuccess: () => { client.invalidateQueries({ queryKey: getListCropsQueryKey() }); setForm({ name: '', variety: '', area: '', stage: 'Vegetative', sowingDate: '' }); setOpen(false); } }); };
  return <Shell><div className="page-enter"><PageIntro eyebrow="Field register" title="My crops" description="Keep each crop's season in view. A little context helps every scan and recommendation stay grounded." action={<button onClick={() => setOpen(!open)} className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-add-crop"><Plus size={16} /> Add a crop</button>} />{open && <Card className="mb-6 p-5 md:p-7"><div className="mb-5 flex items-center justify-between"><div><p className="font-serif text-xl font-semibold">Add a field crop</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">You can edit the details with your field notebook later.</p></div><button onClick={() => setOpen(false)} aria-label="Close add crop form" data-testid="button-close-crop-form"><X size={18} /></button></div><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><label className="text-xs font-semibold">Crop name<input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Cotton" className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-crop-name" /></label><label className="text-xs font-semibold">Variety<input value={form.variety} onChange={(e) => setForm({ ...form, variety: e.target.value })} placeholder="Bt cotton / local variety" className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-crop-variety" /></label><label className="text-xs font-semibold">Area<input value={form.area} onChange={(e) => setForm({ ...form, area: e.target.value })} placeholder="2.5 acres" className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-crop-area" /></label><label className="text-xs font-semibold">Growth stage<select value={form.stage} onChange={(e) => setForm({ ...form, stage: e.target.value })} className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="select-crop-stage"><option>Germination</option><option>Vegetative</option><option>Flowering</option><option>Fruiting</option><option>Harvest ready</option></select></label><label className="text-xs font-semibold">Sowing date<input type="date" value={form.sowingDate} onChange={(e) => setForm({ ...form, sowingDate: e.target.value })} className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-sowing-date" /></label><div className="flex items-end"><button disabled={create.isPending} className="w-full rounded-xl bg-[hsl(var(--accent))] px-4 py-3 text-xs font-bold text-[hsl(var(--accent-foreground))] disabled:opacity-50" data-testid="button-save-crop">{create.isPending ? 'Saving crop…' : 'Save crop'}</button></div></form></Card>}{query.isLoading ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><LoadingBlock className="h-48" /><LoadingBlock className="h-48" /><LoadingBlock className="h-48" /></div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data.map((crop) => <CropDetailCard crop={crop} key={crop.id} />)}</div> : <EmptyState icon={Sprout} title="No crops in the register yet" text="Add cotton, soybean, wheat, or any crop you are growing this season." action={<button onClick={() => setOpen(true)} className="mt-5 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-empty-add-crop">Add first crop</button>} />}</div></Shell>;
}
function CropDetailCard({ crop }: { crop: Crop }) { return <Card className="overflow-hidden"><div className="h-2 bg-[hsl(var(--accent))]" /><div className="p-5"><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Sprout size={21} /></div><span className="rounded-full bg-[hsl(var(--primary)/.1)] px-2.5 py-1 text-[10px] font-semibold text-[hsl(var(--primary))]">{crop.health || 'Tracking'}</span></div><h2 className="mt-5 font-serif text-2xl font-semibold">{crop.name}</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{crop.variety}</p><div className="mt-6 grid grid-cols-2 gap-4 border-t border-[hsl(var(--border))] pt-4"><div><p className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Area</p><p className="mt-1 text-sm font-semibold">{crop.area}</p></div><div><p className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Stage</p><p className="mt-1 text-sm font-semibold">{crop.stage}</p></div></div><p className="mt-4 flex items-center gap-1.5 text-[11px] text-[hsl(var(--muted-foreground))]"><CalendarDays size={13} /> Sown {crop.sowingDate}</p></div></Card>; }

function SoilPage() {
  const query = useListSoilReports({ query: { queryKey: getListSoilReportsQueryKey() } });
  const create = useCreateSoilReport(); const client = useQueryClient();
  const [open, setOpen] = useState(false); const [form, setForm] = useState({ field: '', nitrogen: '', phosphorus: '', potassium: '', ph: '', organicCarbon: '' });
  const submit = (e: FormEvent) => { e.preventDefault(); if (!form.field) return; create.mutate({ data: { field: form.field, nitrogen: Number(form.nitrogen), phosphorus: Number(form.phosphorus), potassium: Number(form.potassium), ph: Number(form.ph), organicCarbon: Number(form.organicCarbon) } }, { onSuccess: () => { client.invalidateQueries({ queryKey: getListSoilReportsQueryKey() }); setOpen(false); setForm({ field: '', nitrogen: '', phosphorus: '', potassium: '', ph: '', organicCarbon: '' }); } }); };
  return <Shell><div className="page-enter"><PageIntro eyebrow="Ground truth" title="Soil reports" description="Enter the numbers from your laboratory report. Patil Agro keeps the history easy to compare, without guessing what the soil did not measure." action={<button onClick={() => setOpen(!open)} className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-add-soil"><Plus size={16} /> Enter lab report</button>} /><div className="mb-7 flex items-start gap-3 rounded-2xl border border-[hsl(var(--accent)/.3)] bg-[hsl(var(--accent)/.08)] p-4 text-xs leading-relaxed text-[hsl(var(--foreground))]"><Info size={17} className="mt-0.5 shrink-0 text-[hsl(var(--accent-foreground))]" /><p>Use values and units exactly as printed by your lab. This page stores your report; a local agronomist should interpret recommendations for your soil and crop.</p></div>{open && <Card className="mb-7 p-5 md:p-7"><div className="mb-5 flex items-center justify-between"><div><p className="font-serif text-xl font-semibold">Record a laboratory report</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Numbers are saved as provided, so keep your original report nearby.</p></div><button onClick={() => setOpen(false)} aria-label="Close soil form" data-testid="button-close-soil-form"><X size={18} /></button></div><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><label className="text-xs font-semibold">Field name<input value={form.field} onChange={(e) => setForm({ ...form, field: e.target.value })} placeholder="North field" className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-soil-field" /></label>{(['nitrogen', 'phosphorus', 'potassium', 'ph', 'organicCarbon'] as const).map((key) => <label className="text-xs font-semibold" key={key}>{key === 'organicCarbon' ? 'Organic carbon' : key.charAt(0).toUpperCase() + key.slice(1)}<input type="number" step="any" value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} placeholder="Enter value" className="focus-ring mt-2 w-full rounded-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid={`input-soil-${key}`} /></label>)}<div className="flex items-end sm:col-span-2 lg:col-span-3"><button disabled={create.isPending} className="rounded-xl bg-[hsl(var(--accent))] px-5 py-3 text-xs font-bold text-[hsl(var(--accent-foreground))] disabled:opacity-50" data-testid="button-save-soil">{create.isPending ? 'Saving report…' : 'Save laboratory report'}</button></div></form></Card>}{query.isLoading ? <div className="grid gap-4 md:grid-cols-2"><LoadingBlock className="h-56" /><LoadingBlock className="h-56" /></div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data.map((soil) => <SoilCard soil={soil} key={soil.id} />)}</div> : <EmptyState icon={FlaskConical} title="No lab reports yet" text="A soil report gives your crop questions a better starting point. Enter one when you have it." action={<button onClick={() => setOpen(true)} className="mt-5 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="button-empty-add-soil">Enter a report</button>} />}</div></Shell>;
}
function SoilCard({ soil }: { soil: SoilReport }) { return <Card className="p-5"><div className="flex items-start justify-between"><div><p className="font-serif text-xl font-semibold">{soil.field}</p><p className="mt-1 font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{soil.date}</p></div><span className="rounded-full bg-[hsl(var(--secondary))] px-2.5 py-1 text-[10px] font-semibold text-[hsl(var(--primary))]">{soil.status || 'Recorded'}</span></div><div className="mt-6 grid grid-cols-4 gap-2">{[['N', soil.nitrogen], ['P', soil.phosphorus], ['K', soil.potassium], ['pH', soil.ph]].map(([key, value]) => <div className="rounded-xl bg-[hsl(var(--background))] p-3" key={key as string}><p className="font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{key}</p><p className="mt-1 text-lg font-semibold">{value}</p></div>)}</div><div className="mt-4 flex justify-between border-t border-[hsl(var(--border))] pt-3 text-xs text-[hsl(var(--muted-foreground))]"><span>Organic carbon</span><strong className="text-[hsl(var(--foreground))]">{soil.organicCarbon}</strong></div></Card>; }

function ReportsPage() {
  const query = useListReports({ query: { queryKey: getListReportsQueryKey() } }); const [filter, setFilter] = useState('All');
  const reports = useMemo(() => { const all = query.data || []; if (filter === 'All') return all; return all.filter((r) => filter === 'Disease' ? !!r.disease : !!r.nutrient); }, [query.data, filter]);
  return <Shell><div className="page-enter"><PageIntro eyebrow="Field memory" title="Saved reports" description="Keep scan results close enough to compare over time. A report is a useful clue, not a final verdict." action={<Link href="/scan" className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-new-report"><ScanLine size={16} /> New scan</Link>} /><div className="mb-5 flex gap-2">{['All', 'Disease', 'Nutrient'].map((item) => <button key={item} onClick={() => setFilter(item)} className={cn('rounded-full px-3.5 py-2 text-xs font-semibold', filter === item ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border border-[hsl(var(--border))] text-[hsl(var(--muted-foreground))]')} data-testid={`button-report-filter-${item.toLowerCase()}`}>{item}</button>)}</div>{query.isLoading ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><LoadingBlock className="h-52" /><LoadingBlock className="h-52" /><LoadingBlock className="h-52" /></div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : reports.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{reports.map((report) => <ReportDetailCard report={report} key={report.id} />)}</div> : <EmptyState icon={FileText} title={filter === 'All' ? 'No saved reports yet' : `No ${filter.toLowerCase()} reports`} text="When you finish a crop scan, choose to keep the result here for future comparison." action={<Link href="/scan" className="mt-5 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-empty-new-report">Start a scan</Link>} />}</div></Shell>;
}
function ReportDetailCard({ report }: { report: Report }) { const [saved, setSaved] = useState(true); return <Card className="overflow-hidden"><div className="h-24 bg-[hsl(var(--secondary))]">{report.imageUrl && <img src={report.imageUrl} alt={`${report.crop} scan`} className="h-full w-full object-cover" />}</div><div className="p-5"><div className="flex items-center justify-between"><span className="font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{report.date}</span><button onClick={() => setSaved(!saved)} className={cn('rounded-lg p-1.5', saved ? 'text-[hsl(var(--accent-foreground))]' : 'text-[hsl(var(--muted-foreground))]')} aria-label="Toggle saved report" data-testid={`button-save-report-${report.id}`}><Check size={15} /></button></div><p className="mt-3 font-serif text-xl font-semibold">{report.crop}</p><p className="mt-1 text-sm">{report.disease || report.nutrient || 'Field observation'}</p><p className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{report.summary || 'No summary was added to this report.'}</p><div className="mt-5 flex gap-4 border-t border-[hsl(var(--border))] pt-4 text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><span>Visual read</span><strong className="text-[hsl(var(--primary))]">{report.diseaseConfidence || report.nutrientConfidence || '—'}%</strong></div></div></Card>; }

function AlertsPage() {
  const query = useListAlerts({ query: { queryKey: getListAlertsQueryKey() } }); const [dismissed, setDismissed] = useState<number[]>([]);
  const alerts = (query.data || []).filter((a) => !dismissed.includes(a.id));
  return <Shell><div className="page-enter"><PageIntro eyebrow="Field signals" title="Alerts & advice" description="Timely notes from your crop, weather, and field context. Dismiss a note when you have seen it." />{query.isLoading ? <div className="space-y-3"><LoadingBlock className="h-28" /><LoadingBlock className="h-28" /></div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : alerts.length ? <div className="max-w-3xl space-y-3">{alerts.map((alert) => <div className="rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-5 shadow-[var(--shadow-sm)]" key={alert.id} data-testid={`card-alert-detail-${alert.id}`}><div className="flex gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--accent)/.14)] text-[hsl(var(--accent-foreground))]"><Bell size={18} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><div><span className="font-mono text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{alert.kind}</span><h2 className="mt-1 font-serif text-xl font-semibold">{alert.title}</h2></div><SeverityPill severity={alert.severity} /></div><p className="mt-3 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">{alert.description}</p><div className="mt-4 flex items-center justify-between border-t border-[hsl(var(--border))] pt-3"><span className="font-mono text-[10px] text-[hsl(var(--muted-foreground))]">{alert.time}</span><button onClick={() => setDismissed([...dismissed, alert.id])} className="inline-flex items-center gap-1.5 text-xs font-bold text-[hsl(var(--primary))]" data-testid={`button-dismiss-alert-${alert.id}`}><Check size={14} /> Seen</button></div></div></div></div>)}</div> : <EmptyState icon={Bell} title="A quiet field desk" text="No open alerts are waiting for you." />}</div></Shell>;
}

function WeatherPage() {
  const dashboardQuery = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } }); const weather = dashboardQuery.data?.weather;
  return <Shell><div className="page-enter"><PageIntro eyebrow="Sky & soil timing" title="Weather desk" description="Weather can change the right moment for irrigation, scouting, and field work. Keep this view close, but observe your own field too." />{dashboardQuery.isLoading ? <div className="grid gap-5 lg:grid-cols-2"><LoadingBlock className="h-72" /><LoadingBlock className="h-72" /></div> : dashboardQuery.isError ? <ErrorState onRetry={() => dashboardQuery.refetch()} /> : weather ? <><div className="grid gap-5 lg:grid-cols-[.78fr_1.22fr]"><WeatherCard weather={weather} large /><Card className="p-6"><div className="flex items-center justify-between"><div><p className="font-serif text-xl font-semibold">Next 7 days</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Forecast for {dashboardQuery.data?.location}</p></div><CloudRain className="text-[hsl(var(--accent))]" size={22} /></div><div className="mt-7 divide-y divide-[hsl(var(--border))]">{weather.forecast?.map((day) => <div className="flex items-center gap-4 py-3 first:pt-0 last:pb-0" key={day.day}><span className="w-20 text-sm font-semibold">{day.day}</span><CloudSun size={19} className="text-[hsl(var(--accent-foreground))]" /><span className="flex-1 text-xs text-[hsl(var(--muted-foreground))]">{day.condition}</span><span className="font-mono text-xs">{day.high}° <span className="text-[hsl(var(--muted-foreground))]">{day.low}°</span></span><span className="flex w-12 items-center justify-end gap-1 text-[10px] text-[hsl(var(--primary))]"><Droplets size={12} />{day.rain}%</span></div>)}</div></Card></div><Card className="mt-6 p-6"><div className="flex gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Leaf size={17} /></div><div><p className="text-xs font-bold uppercase tracking-[.1em] text-[hsl(var(--primary))]">Field note for this weather</p><p className="mt-2 max-w-2xl text-sm leading-relaxed">Plan scouting when leaves are dry and light is even. If rain arrives, revisit spray timing and avoid treating a visual signal without checking the crop in person.</p></div></div></Card></> : <EmptyState icon={CloudSun} title="Weather is not available yet" text="We will show current conditions and the seven-day view when local data comes through." />}</div></Shell>;
}

function AssistantPage() {
  const [language, setLanguage] = useState('मराठी'); const [message, setMessage] = useState(''); const [messages, setMessages] = useState([{ from: 'assistant', text: 'नमस्कार Suresh. तुमच्या शेतासाठी आज मी काय पाहू?' }]);
  const send = (e: FormEvent) => { e.preventDefault(); if (!message.trim()) return; setMessages([...messages, { from: 'user', text: message.trim() }, { from: 'assistant', text: language === 'मराठी' ? 'तुमचा प्रश्न नोंदवला आहे. पिकाचे नाव, वाढीचा टप्पा आणि तुम्ही पाहिलेली लक्षणे सांगा.' : language === 'हिन्दी' ? 'आपका सवाल दर्ज है। फसल का नाम, अवस्था और दिख रहे लक्षण बताइए।' : 'I have noted your question. Tell me the crop, growth stage, and what you can see. ' }]); setMessage(''); };
  return <Shell><div className="page-enter"><PageIntro eyebrow="Your field desk" title="Ask Patil AI" description="A calm place for crop questions in the language you use at the field edge. Ask plainly; context makes the answer safer." /><div className="grid gap-5 lg:grid-cols-[1fr_.65fr]"><Card className="flex min-h-[520px] flex-col overflow-hidden"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-5"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><MessageCircle size={17} /></div><div><p className="text-sm font-bold">Patil Agro AI</p><p className="text-[10px] text-[hsl(var(--muted-foreground))]">Guidance with clear limits</p></div></div><div className="flex gap-1 rounded-lg bg-[hsl(var(--muted))] p-1">{['मराठी', 'हिन्दी', 'English'].map((lang) => <button onClick={() => setLanguage(lang)} key={lang} className={cn('rounded-md px-2 py-1.5 text-[10px] font-semibold', language === lang ? 'bg-[hsl(var(--card))] text-[hsl(var(--primary))] shadow-sm' : 'text-[hsl(var(--muted-foreground))]')} data-testid={`button-language-${lang}`}>{lang}</button>)}</div></div><div className="flex-1 space-y-4 bg-[hsl(var(--background)/.5)] p-5">{messages.map((item, index) => <div key={index} className={cn('flex', item.from === 'user' ? 'justify-end' : 'justify-start')}><div className={cn('max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-relaxed', item.from === 'user' ? 'rounded-br-sm bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'rounded-bl-sm border border-[hsl(var(--border))] bg-[hsl(var(--card))]')}>{item.text}</div></div>)}</div><form onSubmit={send} className="flex gap-2 border-t border-[hsl(var(--border))] p-4"><input value={message} onChange={(e) => setMessage(e.target.value)} placeholder={language === 'मराठी' ? 'तुमचा प्रश्न लिहा…' : 'Write your question…'} className="focus-ring min-w-0 flex-1 rounded-xl border bg-[hsl(var(--background))] px-4 py-3 text-sm outline-none" data-testid="input-assistant-message" /><button className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]" aria-label="Send message" data-testid="button-send-message"><Send size={17} /></button></form></Card><Card className="h-fit p-6"><p className="font-serif text-xl font-semibold">Ask with field context</p><p className="mt-2 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">The more specific your note, the less we have to assume.</p><div className="mt-6 space-y-3">{['Which crop and variety?', 'What growth stage?', 'When did you first notice it?', 'What changed in rain or irrigation?'].map((item, index) => <div className="flex items-center gap-3 rounded-xl bg-[hsl(var(--muted)/.6)] p-3 text-xs" key={item}><span className="font-mono text-[10px] text-[hsl(var(--accent))]">0{index + 1}</span>{item}</div>)}</div><div className="mt-7 border-t border-[hsl(var(--border))] pt-5 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]"><Info size={14} className="mr-1 inline text-[hsl(var(--accent-foreground))]" /> AI guidance can be wrong. Confirm high-impact decisions with a qualified agronomist and the product label.</div></Card></div></div></Shell>;
}

function LoginPage() {
  const [sent, setSent] = useState(false); return <div className="grain min-h-[100dvh] bg-[hsl(var(--primary))] p-5 text-[hsl(var(--primary-foreground))] md:p-10"><div className="mx-auto flex min-h-[calc(100dvh-40px)] max-w-6xl flex-col justify-between"><BrandMark /><div className="grid items-center gap-12 py-14 md:grid-cols-[1fr_.75fr]"><div><div className="mb-5 font-mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--sidebar-primary))]">A better note from the field</div><h1 className="max-w-xl font-serif text-5xl font-semibold leading-[.98] tracking-[-.045em] md:text-7xl">Your farm, seen with a little more clarity.</h1><p className="mt-6 max-w-md text-sm leading-relaxed text-[hsl(var(--primary-foreground)/.68)]">Patil Agro keeps crop observations, weather, soil, and next steps together — made for the rhythms of Indian farming.</p></div><Card className="p-7 text-[hsl(var(--foreground))] md:p-8"><p className="font-serif text-2xl font-semibold">Welcome back</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">Enter your phone number to continue to your field desk.</p>{sent ? <div className="mt-8 rounded-xl bg-[hsl(var(--secondary))] p-5 text-center"><Check className="mx-auto text-[hsl(var(--primary))]" size={23} /><p className="mt-3 text-sm font-semibold">A sign-in code is on its way</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">For this demo, continue to your dashboard.</p><Link href="/" className="mt-5 inline-flex rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-login-dashboard">Go to dashboard</Link></div> : <form onSubmit={(e) => { e.preventDefault(); setSent(true); }} className="mt-8"><label className="text-xs font-semibold">Mobile number<div className="mt-2 flex"><span className="flex items-center rounded-l-xl border border-r-0 bg-[hsl(var(--muted))] px-3 text-sm text-[hsl(var(--muted-foreground))]">+91</span><input required type="tel" placeholder="98765 43210" className="focus-ring min-w-0 flex-1 rounded-r-xl border bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none" data-testid="input-login-phone" /></div></label><button className="mt-4 w-full rounded-xl bg-[hsl(var(--accent))] px-4 py-3.5 text-xs font-bold text-[hsl(var(--accent-foreground))]" data-testid="button-send-login-code">Send sign-in code <ArrowUpRight className="ml-1 inline" size={14} /></button><p className="mt-5 text-center text-[10px] leading-relaxed text-[hsl(var(--muted-foreground))]">By continuing, you agree to keep your account details private and use guidance thoughtfully.</p></form>}</Card></div><div className="flex items-center justify-between text-[10px] text-[hsl(var(--primary-foreground)/.5)]"><span>© Patil Agro Solution</span><span>Made for the people who grow India</span></div></div></div>;
}

export { DashboardPage, ScanPage, CropsPage, SoilPage, ReportsPage, AlertsPage, WeatherPage, AssistantPage, LoginPage };